// Auto-migration hook: upgrades cached definitions & sentences while preserving user mastery stats
(function() {
  if (typeof window === 'undefined') return;
  try {
    const raw = localStorage.getItem('lexisoup_vocabulary');
    if (raw) {
      const items = JSON.parse(raw);
      const map = new Map(window.DEFAULT_VOCABULARY.map(v => [v.word.toLowerCase(), v]));
      items.forEach(item => {
        const fresh = map.get(item.word.toLowerCase());
        if (fresh) {
          item.definition = fresh.definition;
          item.synonyms = fresh.synonyms;
          item.swipeCards = fresh.swipeCards;
          item.chatChallenge = fresh.chatChallenge;
          item.synonymChallenge = fresh.synonymChallenge;
        }
      });
      localStorage.setItem('lexisoup_vocabulary', JSON.stringify(items));
    }
  } catch (e) {}

  try {
    if (window.indexedDB) {
      const req = indexedDB.open('LexiSoupDB', 1);
      req.onsuccess = function(e) {
        const db = e.target.result;
        if (db.objectStoreNames.contains('vocabulary')) {
          const tx = db.transaction('vocabulary', 'readwrite');
          const store = tx.objectStore('vocabulary');
          const getAllReq = store.getAll();
          getAllReq.onsuccess = function() {
            const stored = getAllReq.result;
            if (stored && stored.length > 0) {
              const map = new Map(window.DEFAULT_VOCABULARY.map(v => [v.word.toLowerCase(), v]));
              stored.forEach(item => {
                const fresh = map.get(item.word.toLowerCase());
                if (fresh) {
                  item.definition = fresh.definition;
                  item.synonyms = fresh.synonyms;
                  item.swipeCards = fresh.swipeCards;
                  item.chatChallenge = fresh.chatChallenge;
                  item.synonymChallenge = fresh.synonymChallenge;
                  store.put(item);
                }
              });
            }
          };
        }
      };
    }
  } catch (e) {}
})();
